def compute(vars):
    old_millions = vars["v1"] / 1000
    new_millions = vars["v2"]
    change_ratio = (new_millions - old_millions) / old_millions
    percentage_change = change_ratio * 100

    return {
        "value": percentage_change,
        "trace": {
            "old_millions": old_millions,
            "new_millions": new_millions,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
